CREATE TABLE public.blocks (blocker_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, blocked_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(blocker_id,blocked_id), CHECK(blocker_id<>blocked_id));
GRANT SELECT, INSERT, DELETE ON public.blocks TO authenticated;
GRANT ALL ON public.blocks TO service_role;
ALTER TABLE public.blocks ENABLE ROW LEVEL SECURITY;
CREATE POLICY blocks_read ON public.blocks FOR SELECT TO authenticated USING(auth.uid() IN (blocker_id,blocked_id));
CREATE POLICY blocks_insert ON public.blocks FOR INSERT TO authenticated WITH CHECK(auth.uid()=blocker_id);
CREATE POLICY blocks_delete ON public.blocks FOR DELETE TO authenticated USING(auth.uid()=blocker_id);
CREATE FUNCTION public.is_blocked(a uuid,b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IN (a,b) AND EXISTS(SELECT 1 FROM public.blocks WHERE (blocker_id=a AND blocked_id=b) OR (blocker_id=b AND blocked_id=a)) $$;
REVOKE ALL ON FUNCTION public.is_blocked(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.is_blocked(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.are_friends(a uuid,b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IN (a,b) AND NOT public.is_blocked(a,b) AND EXISTS(SELECT 1 FROM public.friendships WHERE status='accepted' AND ((requester_id=a AND recipient_id=b) OR(requester_id=b AND recipient_id=a))) $$;
CREATE FUNCTION public.guard_social_pair() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a uuid; b uuid; BEGIN IF TG_TABLE_NAME='blocks' THEN a:=NEW.blocker_id; b:=NEW.blocked_id; ELSIF TG_TABLE_NAME='messages' THEN a:=NEW.sender_id; b:=NEW.recipient_id; ELSE a:=NEW.requester_id; b:=NEW.recipient_id; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(least(a,b)::text||greatest(a,b)::text,0)); IF TG_TABLE_NAME='blocks' THEN DELETE FROM public.friendships WHERE (requester_id=a AND recipient_id=b) OR(requester_id=b AND recipient_id=a); ELSE IF EXISTS(SELECT 1 FROM public.blocks WHERE (blocker_id=a AND blocked_id=b) OR(blocker_id=b AND blocked_id=a)) THEN RAISE EXCEPTION 'Interaction unavailable'; END IF; IF TG_TABLE_NAME='messages' AND NOT public.are_friends(a,b) THEN RAISE EXCEPTION 'Friends only'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER block_disconnect BEFORE INSERT ON public.blocks FOR EACH ROW EXECUTE FUNCTION public.guard_social_pair();
CREATE TRIGGER friendship_guard BEFORE INSERT OR UPDATE ON public.friendships FOR EACH ROW EXECUTE FUNCTION public.guard_social_pair();
CREATE TRIGGER message_guard BEFORE INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION public.guard_social_pair();
DROP POLICY friendship_request ON public.friendships;
CREATE POLICY friendship_request ON public.friendships FOR INSERT TO authenticated WITH CHECK(requester_id=auth.uid() AND status='pending' AND NOT public.is_blocked(requester_id,recipient_id));
DROP POLICY message_read ON public.messages;
CREATE POLICY message_read ON public.messages FOR SELECT TO authenticated USING(auth.uid() IN(sender_id,recipient_id) AND NOT public.is_blocked(sender_id,recipient_id));
DROP POLICY "see own or public tags" ON public.user_tags;
CREATE POLICY "see own or public tags" ON public.user_tags FOR SELECT TO authenticated USING(user_id=auth.uid() OR(is_public AND NOT public.is_blocked(user_id,auth.uid())));
CREATE OR REPLACE FUNCTION public.shared_gallery_access(path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.stories s WHERE s.storage_path=path AND public.can_view_story(s.id)) OR EXISTS(SELECT 1 FROM public.messages m WHERE m.storage_path=path AND auth.uid() IN(m.sender_id,m.recipient_id) AND NOT public.is_blocked(m.sender_id,m.recipient_id)) $$;
CREATE OR REPLACE FUNCTION public.mark_messages_read(friend_id uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.messages SET read_at=now() WHERE recipient_id=auth.uid() AND sender_id=friend_id AND read_at IS NULL AND NOT public.is_blocked(friend_id,auth.uid()) $$;
CREATE OR REPLACE FUNCTION public.tag_counts() RETURNS TABLE(tag_id uuid,followers bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT ut.tag_id,count(*) FROM public.user_tags ut WHERE ut.is_public AND auth.uid() IS NOT NULL AND NOT public.is_blocked(ut.user_id,auth.uid()) GROUP BY ut.tag_id $$;
ALTER TABLE public.profiles ADD COLUMN bio_public boolean NOT NULL DEFAULT true;
REVOKE SELECT ON public.profiles FROM authenticated,anon;
GRANT SELECT(id,username,display_name,avatar_url,onboarded,created_at) ON public.profiles TO authenticated;
CREATE FUNCTION public.my_private_profile() RETURNS SETOF public.profiles LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT * FROM public.profiles WHERE id=auth.uid() $$;
CREATE FUNCTION public.visible_profile(handle text) RETURNS TABLE(id uuid,username text,display_name text,bio text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.username,p.display_name,CASE WHEN p.id=auth.uid() OR p.bio_public THEN p.bio ELSE NULL END FROM public.profiles p WHERE p.username=handle AND auth.uid() IS NOT NULL $$;
REVOKE ALL ON FUNCTION public.my_private_profile(),public.visible_profile(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.my_private_profile(),public.visible_profile(text) TO authenticated;
REVOKE EXECUTE ON FUNCTION public.accept_friend(uuid),public.are_friends(uuid,uuid),public.can_view_story(uuid),public.shared_gallery_access(text),public.mark_messages_read(uuid),public.tag_counts(),public.guard_social_pair(),public.award_social_points(),public.handle_new_user(),public.normalize_story() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.accept_friend(uuid),public.are_friends(uuid,uuid),public.can_view_story(uuid),public.shared_gallery_access(text),public.mark_messages_read(uuid),public.tag_counts(),public.normalize_story() TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.blocks,public.story_views,public.point_events;
CREATE INDEX blocks_reverse ON public.blocks(blocked_id,blocker_id);
CREATE INDEX user_tags_discovery ON public.user_tags(tag_id,user_id) WHERE is_public;
CREATE INDEX stories_expiry ON public.stories(expires_at);
CREATE INDEX media_owner_path ON public.media(owner_id,storage_path);